mapper.select:
select
a.id,
a.patient_id as patientId,
a.org_id as orgId,
a.dentist_id as dentistId,
a.assistant_id as assistantId,
a.dept_room_id as deptRoomId,
a.clinic_device_item_id as clinicDeviceItemId,
a.clinic_appoint_item_id as clinicAppointItemId,
a.appoint_duration as appointDuration,
a.appoint_date as appointDate,
a.appoint_time as appointTime,
a.appoint_start_time as appointStartTime,
a.appoint_end_time as appointEndTime,
a.appoint_period as appointPeriod,
a.appoint_type as appointType,
a.confirm_status as confirmStatus,
a.appoint_status as appointStatus,
a.tooth_bit as toothBit,
IFNULL(a.appoint_content,'--') as appointContent,
IFNULL(a.remarks,'--') as remarks,
IFNULL(a.cancel_reason,'--') as cancelReason,
a.inservice,
a.crt_name as crtName,
a.crt_time as crtTime
from appointment a


        and a.org_id = #{query.orgId}


        and a.inservice = #{query.inservice}


        and a.appoint_status = #{query.appointStatus}


        and a.patient_id = #{query.patientId}



        and a.dentist_id = #{query.dentistId}


        and a.assistant_id = #{query.assistantId}


        and a.dept_room_id = #{query.deptRoomId}


        and a.clinic_device_item_id = #{query.clinicDeviceItemId}


        and a.clinic_appoint_item_id = #{query.clinicAppointItemId}


        and a.appoint_date = DATE_FORMAT(#{query.appointDate},'%Y-%m-%d')


        and a.appoint_time = #{query.appointTime}


        and a.appoint_start_time = #{query.appointStartTime}


        and a.appoint_end_time = #{query.appointEndTime}


        and a.appoint_type = #{query.appointType}


        and a.confirmStatus = #{query.confirmStatus}

    and a.appoint_status <> 2

order by a.appoint_start_time asc

select a.id, a.dentist_id, -- a.appoint_date as currentDate, a.patient_id, a.appoint_type, a.appoint_content, a.appoint_date, a.appoint_time, a.appoint_duration, a.confirm_status, (select COUNT(a1.dentist_id) as num from appointment a1 where a1.dentist_id = a.dentist_id and a1.inservice = 1 and a1.appoint_date between DATE_FORMAT(#{startDate},'%Y-%m-%d') and DATE_FORMAT(#{endDate},'%Y-%m-%d') and a1.org_id = a.org_id and a1.appoint_status <> 3) as patientNum from appointment a
a.inservice = 1 and a.appoint_status <> 3
and a.org_id = #{orgId}
and a.dentist_id = #{dentistId}
and a.appoint_date between DATE_FORMAT(#{startDate},'%Y-%m-%d') and DATE_FORMAT(#{endDate},'%Y-%m-%d')

select a.id, a.org_id as orgId, a.patient_id as patientId, a.appoint_type as firstVisit, a.dentist_id as appointDentistId, a.assistant_id as appointAssistantId, a.dept_room_id as appointDeptRoomId, a.appoint_time as appointTime, a.appoint_duration as appointDuration, IFNULL(a.appoint_content,'--') as appointContent, IFNULL(a.remarks,'--') as appointRemark, a.appoint_type as appointType, a.appoint_status as appointStatus, a.confirm_status as confirmStatus, DATE_FORMAT(a.crt_time, '%Y-%m-%d') as appointmentCrtTime from appointment a
and a.appoint_status = 0 and a.inservice = 1
and a.id = #{queryForm.id}
and a.dentist_id = #{queryForm.dentistId}
and a.patient_id = #{queryForm.patientId}
and a.org_id = #{queryForm.orgId}
and DATE_FORMAT(a.appoint_date, '%Y-%m-%d') = DATE_FORMAT(#{queryForm.currentDate}, '%Y-%m-%d')
order by IF( #{queryForm.currentDate} > CURRENT_DATE, confirm_status, appointTime ) ASC, appointTime ASC

select a.*
from appointment a
where a.patient_id = #{patientId}

SELECT a.id, a.patient_id AS patientId, a.org_id AS orgId, a.dentist_id AS dentistId, a.assistant_id AS assistantId, a.appoint_duration AS appointDuration, a.appoint_date AS appointDate, a.appoint_time AS appointTime, a.appoint_content AS appointContent, a.confirm_status AS confirmStatus, a.appoint_status AS appointStatus, a.dept_room_id AS deptRoomId, a.clinic_device_item_id AS clinicDeviceItemId, a.remarks FROM appointment a
and a.org_id = #{orgId}
and a.patient_id = #{patientId}
and DATE_FORMAT(a.appoint_date,'%Y-%m-%d') BETWEEN DATE_FORMAT(#{startDate},'%Y-%m-%d') and DATE_FORMAT(#{endDate},'%Y-%m-%d')
order by a.appoint_date desc

select

from appointment a


        and a.org_id = #{query.orgId}


        and DATE_FORMAT(a.appoint_date, '%Y-%m-%d') = #{query.queryDate}


        and a.dentist_id = #{query.dentistId}


        and a.appoint_status = #{query.appointStatus}


        and a.inservice = #{query.inservice}

select count(id) from appointment where patient_id = #{patientId}
and date_format(appoint_date,'%Y-%m-%d') > date_format(now(),'%Y-%m-%d')
and appoint_status = 0

SELECT DATE_FORMAT(a.appoint_date,'%Y-%m-%d') as currentDate, COUNT(a.id) as `count` FROM( SELECT appoint.id, DATE_FORMAT(appoint.appoint_date,'%Y-%m-%d') as appoint_date FROM `appointment` appoint
and appoint.appoint_status in (0,1) and appoint.inservice = true
and appoint.dentist_id = #{dentistId}
and date_format(appoint.appoint_date,'%Y-%m-%d') BETWEEN date_format(#{startDate},'%Y-%m-%d') AND date_format(#{endDate},'%Y-%m-%d')
and org_id = #{orgId}
) a GROUP BY a.appoint_date

select count(a.id) from appointment a
and a.inservice = 1
and a.org_id = #{queryForm.orgId}
and a.appoint_status = 0
and DATE_FORMAT(a.appoint_date, '%Y-%m-%d') = DATE_FORMAT(#{queryForm.currentDate}, '%Y-%m-%d')
and a.dentist_id = #{queryForm.dentistId}

select a.id, a.dentist_id, a.patient_id, a.appoint_type, a.appoint_content, a.appoint_date as currentDate, a.appoint_date, a.appoint_time, a.appoint_duration, a.confirm_status, (select COUNT(a1.dentist_id) as num from appointment a1 where a1.dentist_id = a.dentist_id and a1.inservice = 1 and a1.appoint_status in (0,1) and a1.org_id = a.org_id and a1.appoint_date between DATE_FORMAT(#{startDate},'%Y-%m-%d') and DATE_FORMAT(#{endDate},'%Y-%m-%d') ) as patientNum from appointment a
a.inservice = 1 and a.appoint_status in (0,1)
and a.org_id = #{orgId}
and a.dentist_id in
#{dentistId}
and a.appoint_date between DATE_FORMAT(#{startDate},'%Y-%m-%d') and DATE_FORMAT(#{endDate},'%Y-%m-%d')
